package io.knowledgebrain.space;
import java.time.*;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class GitHubLearningAuthorizationTest extends LearningAuthorizationTest {
 @Test void githubEvidenceIsRegisteredPrivatePersonalOwnerOnly(){var spaces=mock(PersonalSpaceStore.class);var identity=mock(IdentityPrincipalClient.class);var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();var api=new LearningAuthorizationController(spaces,identity,"a".repeat(43));for(String kind:new String[]{"GUEST","REGISTERED"})for(String type:new String[]{"PERSONAL","GROUP","ORGANIZATION","PUBLIC"})for(String visibility:new String[]{"PRIVATE","PUBLIC"})for(String role:new String[]{"OWNER","EDITOR","VIEWER"})for(String action:new String[]{"GITHUB_EVIDENCE_READ","GITHUB_EVIDENCE_WRITE"}){when(identity.resolve("b".repeat(43),null)).thenReturn(new IdentityPrincipalClient.Principal(actor,kind,Instant.now().plusSeconds(60)));when(spaces.visible(space,actor)).thenReturn(new PersonalSpaceStore.SpaceView(space,type,visibility,role));var check=new LearningAuthorizationController.Check(space,"b".repeat(43),action);if(kind.equals("REGISTERED")&&type.equals("PERSONAL")&&visibility.equals("PRIVATE")&&role.equals("OWNER"))assertEquals(actor,api.authorize(check,request()).getBody().principalId());else assertThrows(RuntimeException.class,()->api.authorize(check,request()));}when(spaces.visible(space,actor)).thenReturn(null);assertThrows(RuntimeException.class,()->api.authorize(new LearningAuthorizationController.Check(space,"b".repeat(43),"GITHUB_EVIDENCE_READ"),request()));}
}
